D.items,D.filters,D.types,D.libraryIndex,D.byType={}, {}, {}, {}, {}
D.ammo=require('TW/Data/Ammo')
for i=1,D.filterChunks do
    for _,f in ipairs(require(string.format('TW/Data/Filters%02d',i))) do D.filters[#D.filters+1]=f end
end
for i=1,D.itemChunks do
    for tpl,item in pairs(require(string.format('TW/Data/Items%02d',i))) do
        for _,slot in ipairs(item.slots) do slot.allowed=D.filters[slot.allowed] end
        D.items[tpl]=item
    end
end
-- The first row of a part type is its ordinary model; D.libraryStates maps the
-- geometry-state rows after them (TW/GeometryState).
for index,full in ipairs(D.library) do if D.libraryIndex[full]==nil then D.libraryIndex[full]=index-1 end end
D.libraryStates=D.libraryStates or {}
for tpl,item in pairs(D.items) do
    if not item.isRoot then
        for copy=0,(item.copies or 1)-1 do
            D.types[copy==0 and item.pz or item.pz..'_'..copy]={tpl=tpl,copy=copy}
        end
        -- A magazine shared with another calibre: one item type per calibre.
        for calibre,full in pairs(item.variants or {}) do D.types[full]={tpl=tpl,copy=0,calibre=calibre} end
    end
end
for key,weapon in pairs(D.weapons) do D.byType[weapon.pz]=key end
return D
